// Copies the shared catalogs (../shared/i18n) into lib/i18n/catalog.g.dart, so the app has them
// as constants: no asset loading, and the same texts as the web (ADR 0006).
// Run after editing a catalog:  dart run tool/gen_i18n.dart
// test/i18n_test.dart fails while the generated file is out of date.
import 'dart:convert';
import 'dart:io';

const langs = ['en', 'id'];

String generate(Map<String, Map<String, String>> catalogs) {
  final out = StringBuffer()
    ..writeln('// GENERATED by tool/gen_i18n.dart from shared/i18n. Do not edit by hand.')
    ..writeln('// ignore_for_file: lines_longer_than_80_chars')
    ..writeln()
    ..writeln('const catalogs = <String, Map<String, String>>{');
  for (final lang in langs) {
    out.writeln("  '$lang': {");
    for (final MapEntry(:key, :value) in catalogs[lang]!.entries) {
      out.writeln('    ${jsonEncode(key).replaceAll(r'$', r'\$')}: ${jsonEncode(value).replaceAll(r'$', r'\$')},');
    }
    out.writeln('  },');
  }
  out.writeln('};');
  return out.toString();
}

Map<String, Map<String, String>> readShared([String root = '../shared/i18n']) => {
      for (final lang in langs)
        lang: (jsonDecode(File('$root/$lang.json').readAsStringSync()) as Map<String, dynamic>).cast<String, String>(),
    };

void main() {
  File('lib/i18n/catalog.g.dart').writeAsStringSync(generate(readShared()));
  stdout.writeln('lib/i18n/catalog.g.dart written');
}
